	buildGiroflexVBeams() {
		const group = new Group();
		group.position.set(0, 1.84, 0);
		const beamTex = getGiroflexBeamTexture();
		const groundTex = getGiroflexGroundTexture();
		const beamGeo = new ConeGeometry(2.25, 8.2, 24, 1, true);
		beamGeo.translate(0, -8.2 / 2, 0);
		beamGeo.rotateX(-Math.PI / 2 + .21);
		const groundWidth = 4.2;
		const groundLength = 8.4;
		const groundGeo = new PlaneGeometry(groundWidth, groundLength);
		groundGeo.translate(0, groundLength / 2, 0);
		groundGeo.rotateX(-Math.PI / 2);
		const redGroup = new Group();
		const redBeamMat = new MeshBasicMaterial({
			color: 16719406,
			map: beamTex,
			transparent: true,
			opacity: .52,
			blending: 2,
			side: 2,
			depthWrite: false
		});
		const redGroundMat = new MeshBasicMaterial({
			color: 16714270,
			map: groundTex,
			transparent: true,
			opacity: .58,
			blending: 2,
			side: 2,
			depthWrite: false
		});
		const redCone = new Mesh(beamGeo, redBeamMat);
		redCone.renderOrder = 5;
		redGroup.add(redCone);
		const redGround = new Mesh(groundGeo, redGroundMat);
		redGround.position.y = -1.72;
		redGround.renderOrder = 5;
		redGroup.add(redGround);
		group.add(redGroup);
		const blueGroup = new Group();
		blueGroup.rotation.y = Math.PI;
		const blueBeamMat = new MeshBasicMaterial({
			color: 2001151,
			map: beamTex,
			transparent: true,
			opacity: .52,
			blending: 2,
			side: 2,
			depthWrite: false
		});
		const blueGroundMat = new MeshBasicMaterial({
			color: 1009407,
			map: groundTex,
			transparent: true,
			opacity: .58,
			blending: 2,
			side: 2,
			depthWrite: false
		});
		const blueCone = new Mesh(beamGeo.clone(), blueBeamMat);
		blueCone.renderOrder = 5;
		blueGroup.add(blueCone);
		const blueGround = new Mesh(groundGeo.clone(), blueGroundMat);
		blueGround.position.y = -1.72;
		blueGround.renderOrder = 5;
		blueGroup.add(blueGround);
		group.add(blueGroup);
		group.visible = this.graphicsMode === "ultra" && !this.exploded && !this.isCrushed && !this.inWater;
		this.root.add(group);
		this.giroflexGroup = group;
	}
