//#region src/game/Sound.ts
var Sound = class {
	context;
	master;
	engine;
	engineGain;
	siren;
	sirenGain;
	muted = false;
	async start() {
		if (!this.context) this.createAudio();
		if (this.context?.state === "suspended") await this.context.resume();
	}
	createAudio() {
		const context = new AudioContext();
		const master = context.createGain();
		master.gain.value = this.muted ? 0 : .38;
		master.connect(context.destination);
		const engine = context.createOscillator();
		const engineFilter = context.createBiquadFilter();
		const engineGain = context.createGain();
		engine.type = "sawtooth";
		engine.frequency.value = 48;
		engineFilter.type = "lowpass";
		engineFilter.frequency.value = 210;
		engineGain.gain.value = .012;
		engine.connect(engineFilter).connect(engineGain).connect(master);
		engine.start();
		const siren = context.createOscillator();
		const sirenGain = context.createGain();
		siren.type = "triangle";
		siren.frequency.value = 480;
		sirenGain.gain.value = 0;
		siren.connect(sirenGain).connect(master);
		siren.start();
		this.context = context;
		this.master = master;
		this.engine = engine;
		this.engineGain = engineGain;
		this.siren = siren;
		this.sirenGain = sirenGain;
	}
	update(speed, wantedLevel) {
		if (!this.context) return;
		const now = this.context.currentTime;
		if (this.engine && this.engineGain) {
			this.engine.frequency.setTargetAtTime(48 + Math.abs(speed) * 3.2, now, .08);
			this.engineGain.gain.setTargetAtTime(.009 + Math.min(.04, Math.abs(speed) * 9e-4), now, .1);
		}
		if (this.siren && this.sirenGain) {
			this.siren.frequency.setTargetAtTime(440 + Math.sin(now * 6) * 125, now, .08);
			this.sirenGain.gain.setTargetAtTime(wantedLevel > 0 ? .018 + wantedLevel * .0015 : 0, now, .25);
		}
	}
	effect(kind) {
		if (!this.context || this.muted) return;
		const context = this.context;
		const now = context.currentTime;
		if (kind === "countdown_beep") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			osc.type = "triangle";
			osc.frequency.setValueAtTime(440, now);
			gain.gain.setValueAtTime(.28, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .18);
			osc.connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .18);
			return;
		}
		if (kind === "countdown_go") {
			[880, 1046.5].forEach((freq, idx) => {
				const osc = context.createOscillator();
				const gain = context.createGain();
				osc.type = "triangle";
				osc.frequency.setValueAtTime(freq, now + idx * .07);
				gain.gain.setValueAtTime(.35, now + idx * .07);
				gain.gain.exponentialRampToValueAtTime(.001, now + idx * .07 + .35);
				osc.connect(gain).connect(this.master);
				osc.start(now + idx * .07);
				osc.stop(now + idx * .07 + .36);
			});
			return;
		}
		if (kind === "upgrade") {
			[
				523.25,
				659.25,
				783.99,
				1046.5
			].forEach((freq, idx) => {
				const osc = context.createOscillator();
				const gain = context.createGain();
				osc.type = "triangle";
				osc.frequency.setValueAtTime(freq, now + idx * .08);
				gain.gain.setValueAtTime(.22, now + idx * .08);
				gain.gain.exponentialRampToValueAtTime(.001, now + idx * .08 + .22);
				osc.connect(gain).connect(this.master);
				osc.start(now + idx * .08);
				osc.stop(now + idx * .08 + .24);
			});
			return;
		}
		if (kind === "jump") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			const filter = context.createBiquadFilter();
			osc.type = "sawtooth";
			osc.frequency.setValueAtTime(140, now);
			osc.frequency.exponentialRampToValueAtTime(540, now + .35);
			filter.type = "lowpass";
			filter.frequency.setValueAtTime(800, now);
			gain.gain.setValueAtTime(.3, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .4);
			osc.connect(filter).connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .4);
			return;
		}
		if (kind === "winch") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			osc.type = "triangle";
			osc.frequency.setValueAtTime(320, now);
			osc.frequency.setValueAtTime(480, now + .06);
			osc.frequency.setValueAtTime(620, now + .12);
			osc.frequency.setValueAtTime(740, now + .18);
			gain.gain.setValueAtTime(.24, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .28);
			osc.connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .28);
			return;
		}
		if (kind === "transform") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			const filter = context.createBiquadFilter();
			osc.type = "sawtooth";
			osc.frequency.setValueAtTime(160, now);
			osc.frequency.linearRampToValueAtTime(580, now + .16);
			osc.frequency.linearRampToValueAtTime(280, now + .32);
			osc.frequency.linearRampToValueAtTime(740, now + .48);
			filter.type = "bandpass";
			filter.frequency.setValueAtTime(1400, now);
			filter.Q.value = 3.5;
			gain.gain.setValueAtTime(.28, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .52);
			osc.connect(filter).connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .52);
			return;
		}
		if (kind === "laser") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			const filter = context.createBiquadFilter();
			osc.type = "sawtooth";
			osc.frequency.setValueAtTime(980, now);
			osc.frequency.exponentialRampToValueAtTime(60, now + .14);
			filter.type = "bandpass";
			filter.frequency.setValueAtTime(2200, now);
			filter.Q.value = 2.5;
			gain.gain.setValueAtTime(.32, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .15);
			osc.connect(filter).connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .15);
			return;
		}
		if (kind === "shoot") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			const filter = context.createBiquadFilter();
			osc.type = "sawtooth";
			osc.frequency.setValueAtTime(480, now);
			osc.frequency.exponentialRampToValueAtTime(90, now + .09);
			filter.type = "bandpass";
			filter.frequency.setValueAtTime(1200, now);
			filter.Q.value = 2;
			gain.gain.setValueAtTime(.25, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .09);
			osc.connect(filter).connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .09);
			return;
		}
		if (kind === "roar") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			const filter = context.createBiquadFilter();
			osc.type = "sawtooth";
			osc.frequency.setValueAtTime(95, now);
			osc.frequency.linearRampToValueAtTime(140, now + .25);
			osc.frequency.exponentialRampToValueAtTime(45, now + .9);
			filter.type = "lowpass";
			filter.frequency.setValueAtTime(400, now);
			gain.gain.setValueAtTime(.42, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .95);
			osc.connect(filter).connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .95);
			return;
		}
		if (kind === "explosion") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			const filter = context.createBiquadFilter();
			osc.type = "sawtooth";
			osc.frequency.setValueAtTime(140, now);
			osc.frequency.exponentialRampToValueAtTime(20, now + .7);
			filter.type = "lowpass";
			filter.frequency.setValueAtTime(600, now);
			filter.frequency.exponentialRampToValueAtTime(80, now + .7);
			gain.gain.setValueAtTime(.48, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .75);
			osc.connect(filter).connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .75);
			return;
		}
		if (kind === "ring") {
			const osc1 = context.createOscillator();
			const osc2 = context.createOscillator();
			const gain1 = context.createGain();
			const gain2 = context.createGain();
			osc1.type = "sine";
			osc1.frequency.setValueAtTime(880, now);
			osc1.frequency.exponentialRampToValueAtTime(1760, now + .22);
			gain1.gain.setValueAtTime(.24, now);
			gain1.gain.exponentialRampToValueAtTime(.001, now + .25);
			osc1.connect(gain1).connect(this.master);
			osc1.start(now);
			osc1.stop(now + .25);
			osc2.type = "triangle";
			osc2.frequency.setValueAtTime(1320, now + .05);
			osc2.frequency.exponentialRampToValueAtTime(2640, now + .28);
			gain2.gain.setValueAtTime(.18, now + .05);
			gain2.gain.exponentialRampToValueAtTime(.001, now + .3);
			osc2.connect(gain2).connect(this.master);
			osc2.start(now + .05);
			osc2.stop(now + .3);
			return;
		}
		if (kind === "takeoff") {
			const osc = context.createOscillator();
			const gain = context.createGain();
			osc.type = "sawtooth";
			osc.frequency.setValueAtTime(120, now);
			osc.frequency.exponentialRampToValueAtTime(420, now + .8);
			gain.gain.setValueAtTime(.25, now);
			gain.gain.exponentialRampToValueAtTime(.001, now + .85);
			osc.connect(gain).connect(this.master);
			osc.start(now);
			osc.stop(now + .85);
			return;
		}
		const oscillator = context.createOscillator();
		const gain = context.createGain();
		const [start, end, duration] = {
			coin: [
				720,
				1180,
				.09
			],
			crash: [
				125,
				48,
				.18
			],
			mission: [
				520,
				1040,
				.22
			],
			wanted: [
				340,
				680,
				.12
			]
		}[kind];
		oscillator.type = kind === "crash" ? "triangle" : "sine";
		oscillator.frequency.setValueAtTime(start, now);
		oscillator.frequency.exponentialRampToValueAtTime(end, now + duration);
		gain.gain.setValueAtTime(kind === "crash" ? .18 : .12, now);
		gain.gain.exponentialRampToValueAtTime(.001, now + duration);
		oscillator.connect(gain).connect(this.master);
		oscillator.start(now);
		oscillator.stop(now + duration);
	}
	toggle() {
		this.muted = !this.muted;
		if (this.master && this.context) this.master.gain.setTargetAtTime(this.muted ? 0 : .38, this.context.currentTime, .04);
		return !this.muted;
	}
	dispose() {
		this.engine?.stop();
		this.siren?.stop();
		this.context?.close();
	}
};
