			const angle = (Math.random() - .5) * Math.PI * .8;
			const cosA = Math.cos(angle);
			const sinA = Math.sin(angle);
			const dirX = normalX * cosA - normalZ * sinA;
			const dirZ = normalX * sinA + normalZ * cosA;
			const speed = 2.5 + Math.random() * 6.5;
			positions[index * 3] = position.x + (Math.random() - .5) * .5;
			positions[index * 3 + 1] = position.y + (Math.random() - .5) * .5;
			positions[index * 3 + 2] = position.z + (Math.random() - .5) * .5;
