//#region src/game/TimeTrial.ts
var TimeTrial = class {
	scene;
	sound;
	sparks;
	root = new Group();
	arches = [];
	active = false;
	currentStage = 1;
	totalStages = 3;
	timeRemaining = 0;
	stageMaxTime = 35;
	totalTimeElapsed = 0;
	lastBeepSecond = -1;
	archCooldownTimer = 0;
	guideLineGroup = new Group();
	guideLineMaterial;
	guideLineTexture;
	stageMeshes = [];
	onStageChanged;
	onTimeTick;
	onCheckpointPassed;
	onVictory;
	onGameOver;
	onToast;
	constructor(scene, sound, sparks, _city) {
		this.scene = scene;
		this.sound = sound;
		this.sparks = sparks;
		this.scene.add(this.root);
		this.root.add(this.guideLineGroup);
		this.buildArches();
		this.buildGuideLines();
		this.setIdleState();
	}
	setGraphicsMode(mode) {
		const boost = mode === "ultra" ? 3 : mode === "high" ? 2.2 : 1.2;
		for (const arch of this.arches) if (arch.neonMesh.material instanceof MeshStandardMaterial) arch.neonMesh.material.emissiveIntensity = boost;
	}
	buildArches() {
		const archConfigs = [
			{
				id: 0,
				name: "⏱️ LARGADA",
				stageLabel: "LARGADA",
				pos: new Vector3(48, 0, 24),
				yaw: 0,
				colorHex: 16436245
			},
			{
				id: 1,
				name: "⚡ ETAPA 1",
				stageLabel: "CHECKPOINT 1",
				pos: new Vector3(120, 0, 144),
				yaw: Math.PI / 2,
				colorHex: 440020
			},
			{
				id: 2,
				name: "⚡ ETAPA 2",
				stageLabel: "CHECKPOINT 2",
				pos: new Vector3(0, 0, -48),
				yaw: Math.PI / 2,
				colorHex: 11032055
			},
			{
				id: 3,
				name: "🏁 CHEGADA",
				stageLabel: "CHEGADA FINAL",
				pos: new Vector3(0, 0, 48),
				yaw: 0,
				colorHex: 2278750
			}
		];
		const streetSpan = 15.6;
		const archHeight = 6.8;
		for (const cfg of archConfigs) {
			const group = new Group();
			group.position.copy(cfg.pos);
			group.rotation.y = cfg.yaw;
			const pillarGeo = new BoxGeometry(1.2, archHeight, 1.2);
			const pillarMat = new MeshStandardMaterial({
				color: 1976635,
				metalness: .8,
				roughness: .3
			});
			const leftPillar = new Mesh(pillarGeo, pillarMat);
			leftPillar.position.set(-15.6 / 2, archHeight / 2, 0);
			group.add(leftPillar);
			const rightPillar = new Mesh(pillarGeo, pillarMat);
			rightPillar.position.set(streetSpan / 2, archHeight / 2, 0);
			group.add(rightPillar);
			const baseGeo = new BoxGeometry(2, 1.2, 2);
			const baseMat = new MeshStandardMaterial({
				color: 6583435,
				roughness: .9
			});
			const leftBase = new Mesh(baseGeo, baseMat);
			leftBase.position.set(-15.6 / 2, .6, 0);
			group.add(leftBase);
			const rightBase = new Mesh(baseGeo, baseMat);
			rightBase.position.set(streetSpan / 2, .6, 0);
			group.add(rightBase);
			const beam = new Mesh(new BoxGeometry(16.8, 1, 1.4), pillarMat);
			beam.position.set(0, 7.3, 0);
			group.add(beam);
			const neonMat = new MeshStandardMaterial({
				color: cfg.colorHex,
				emissive: cfg.colorHex,
				emissiveIntensity: 2.2,
				roughness: .1
			});
			const topNeon = new Mesh(new BoxGeometry(15.4, .22, .22), neonMat);
			topNeon.position.set(0, 6.7, 0);
			group.add(topNeon);
			const sideNeonGeo = new BoxGeometry(.22, archHeight, .22);
			const leftNeon = new Mesh(sideNeonGeo, neonMat);
			leftNeon.position.set(-7.2, archHeight / 2, 0);
			group.add(leftNeon);
			const rightNeon = new Mesh(sideNeonGeo, neonMat);
			rightNeon.position.set(streetSpan / 2 - .6, archHeight / 2, 0);
			group.add(rightNeon);
			const sign = new Mesh(new BoxGeometry(8.5, 1.6, .3), new MeshStandardMaterial({
				color: 988970,
				emissive: cfg.colorHex,
				emissiveIntensity: .8,
				roughness: .2
			}));
			sign.position.set(0, 8.6, 0);
			group.add(sign);
			const canvas = document.createElement("canvas");
			canvas.width = 512;
			canvas.height = 128;
			const ctx = canvas.getContext("2d");
			ctx.fillStyle = "#090d16";
			ctx.fillRect(0, 0, 512, 128);
			ctx.strokeStyle = `#${cfg.colorHex.toString(16).padStart(6, "0")}`;
			ctx.lineWidth = 8;
			ctx.strokeRect(4, 4, 504, 120);
			ctx.fillStyle = `#${cfg.colorHex.toString(16).padStart(6, "0")}`;
			ctx.font = "900 40px sans-serif";
			ctx.textAlign = "center";
			ctx.textBaseline = "middle";
			ctx.fillText(cfg.name, 256, 64);
			const labelMat = new MeshBasicMaterial({
				map: new CanvasTexture(canvas),
				transparent: true
			});
			const labelMesh = new Mesh(new PlaneGeometry(8.2, 1.4), labelMat);
			labelMesh.position.set(0, 8.6, .18);
			group.add(labelMesh);
			const labelMeshBack = labelMesh.clone();
			labelMeshBack.rotation.y = Math.PI;
			labelMeshBack.position.z = -.18;
			group.add(labelMeshBack);
			const holo = new Mesh(new PlaneGeometry(14.4, 6.3), new MeshBasicMaterial({
				color: cfg.colorHex,
				transparent: true,
				opacity: .22,
				side: 2,
				depthWrite: false,
				blending: 2
			}));
			holo.position.set(0, 6.3 / 2, 0);
			group.add(holo);
			this.root.add(group);
			this.arches.push({
				id: cfg.id,
				name: cfg.name,
				stageLabel: cfg.stageLabel,
				position: cfg.pos.clone(),
				yaw: cfg.yaw,
				group,
				neonMesh: topNeon,
				signMesh: sign,
				hologramMesh: holo,
				colorHex: cfg.colorHex
			});
		}
	}
	createChevronTexture() {
		const canvas = document.createElement("canvas");
		canvas.width = 256;
		canvas.height = 64;
		const ctx = canvas.getContext("2d");
		ctx.clearRect(0, 0, 256, 64);
		ctx.fillStyle = "rgba(6, 182, 212, 0.25)";
		ctx.fillRect(0, 16, 256, 32);
		ctx.strokeStyle = "#22d3ee";
		ctx.lineWidth = 3;
		ctx.beginPath();
		ctx.moveTo(0, 16);
		ctx.lineTo(256, 16);
		ctx.moveTo(0, 48);
		ctx.lineTo(256, 48);
		ctx.stroke();
		ctx.fillStyle = "#67e8f9";
		for (let x = 32; x < 256; x += 64) {
			ctx.beginPath();
			ctx.moveTo(x - 14, 20);
			ctx.lineTo(x + 14, 32);
			ctx.lineTo(x - 14, 44);
			ctx.lineTo(x - 4, 32);
			ctx.closePath();
			ctx.fill();
		}
		const texture = new CanvasTexture(canvas);
		texture.wrapS = RepeatWrapping;
		texture.wrapT = ClampToEdgeWrapping;
		return texture;
	}
	buildGuideLines() {
		this.guideLineTexture = this.createChevronTexture();
		this.guideLineMaterial = new MeshBasicMaterial({
			map: this.guideLineTexture,
			transparent: true,
			opacity: .88,
			depthWrite: false,
			blending: 2,
			side: 2
		});
		const pointsStage1 = [
			new Vector3(48, .05, 24),
			new Vector3(48, .05, 136),
			new Vector3(56, .05, 144),
			new Vector3(120, .05, 144)
		];
		const mesh1 = this.createRoadRibbon(pointsStage1, 2.2, 14);
		this.guideLineGroup.add(mesh1);
		this.stageMeshes.push(mesh1);
		const pointsStage2 = [
			new Vector3(120, .05, 144),
			new Vector3(138, .05, 144),
			new Vector3(144, .05, 136),
			new Vector3(144, .05, -40),
			new Vector3(136, .05, -48),
			new Vector3(0, .05, -48)
		];
		const mesh2 = this.createRoadRibbon(pointsStage2, 2.2, 24);
		this.guideLineGroup.add(mesh2);
		this.stageMeshes.push(mesh2);
		const pointsStage3 = [
			new Vector3(0, .05, -48),
			new Vector3(-40, .05, -48),
			new Vector3(-48, .05, -40),
			new Vector3(-48, .05, 40),
			new Vector3(-40, .05, 48),
			new Vector3(0, .05, 48)
		];
		const mesh3 = this.createRoadRibbon(pointsStage3, 2.2, 16);
		this.guideLineGroup.add(mesh3);
		this.stageMeshes.push(mesh3);
	}
	createRoadRibbon(waypoints, width, textureRepeat) {
		const curve = new CatmullRomCurve3(waypoints, false, "catmullrom", .15);
		const samples = 80;
		const points = curve.getPoints(samples);
		const positions = [];
		const uvs = [];
		const indices = [];
		const up = new Vector3(0, 1, 0);
		const halfW = width / 2;
		for (let i = 0; i <= samples; i++) {
			const p = points[i];
			const t = curve.getTangent(i / samples).normalize();
			const normal = new Vector3().crossVectors(t, up).normalize();
			positions.push(p.x - normal.x * halfW, p.y, p.z - normal.z * halfW);
			positions.push(p.x + normal.x * halfW, p.y, p.z + normal.z * halfW);
			const u = i / samples * textureRepeat;
			uvs.push(u, 0);
			uvs.push(u, 1);
			if (i < samples) {
				const base = i * 2;
				indices.push(base, base + 1, base + 2);
				indices.push(base + 1, base + 3, base + 2);
			}
		}
		const geometry = new BufferGeometry();
		geometry.setAttribute("position", new Float32BufferAttribute(positions, 3));
		geometry.setAttribute("uv", new Float32BufferAttribute(uvs, 2));
		geometry.setIndex(indices);
		geometry.computeVertexNormals();
		return new Mesh(geometry, this.guideLineMaterial);
	}
	setIdleState() {
		this.active = false;
		this.currentStage = 1;
		this.timeRemaining = 0;
		this.totalTimeElapsed = 0;
		this.guideLineGroup.visible = false;
		for (const arch of this.arches) if (arch.id === 0) {
			arch.group.visible = true;
			arch.hologramMesh.visible = true;
		} else arch.group.visible = false;
	}
	startMission() {
		if (this.active) return;
		this.active = true;
		this.currentStage = 1;
		this.stageMaxTime = 35;
		this.timeRemaining = this.stageMaxTime;
		this.totalTimeElapsed = 0;
		this.archCooldownTimer = 1.5;
		for (const arch of this.arches) {
			arch.group.visible = true;
			arch.hologramMesh.visible = true;
		}
		this.guideLineGroup.visible = true;
		this.updateActiveStageLine(1);
		this.sound.effect("countdown_go");
		this.sound.effect("mission");
		this.sparks.emit(this.arches[0].position);
		this.onStageChanged?.(1, this.totalStages, this.timeRemaining);
		this.onToast?.("⏱️ CORRIDA CONTRA O TEMPO INICIADA! SIGA A LINHA NO CHÃO ATÉ O ARCO DA ETAPA 1!");
	}
	updateActiveStageLine(stage) {
		for (let i = 0; i < this.stageMeshes.length; i++) this.stageMeshes[i].visible = i + 1 === stage;
	}
	advanceStage(targetStage) {
		this.currentStage = targetStage;
		this.archCooldownTimer = 1.8;
		if (targetStage === 2) {
			this.stageMaxTime = 45;
			this.timeRemaining = this.stageMaxTime;
			this.sound.effect("coin");
			this.sound.effect("upgrade");
			this.sparks.emit(this.arches[1].position);
			this.onCheckpointPassed?.(1);
			this.onToast?.("⚡ ETAPA 1 CONCLUÍDA! CRONÔMETRO REINICIADO (+45s)! SIGA PARA O ARCO DA ETAPA 2!");
		} else if (targetStage === 3) {
			this.stageMaxTime = 35;
			this.timeRemaining = this.stageMaxTime;
			this.sound.effect("coin");
			this.sound.effect("upgrade");
			this.sparks.emit(this.arches[2].position);
			this.onCheckpointPassed?.(2);
			this.onToast?.("⚡ ETAPA 2 CONCLUÍDA! RETA FINAL (+35s)! ACELERE ATÉ A CHEGADA!");
		}
		this.updateActiveStageLine(targetStage);
		this.onStageChanged?.(targetStage, this.totalStages, this.timeRemaining);
	}
	completeVictory() {
		this.active = false;
		this.sound.effect("upgrade");
		this.sparks.emit(this.arches[3].position);
		this.onVictory?.(7500, 15e3, 350, this.totalTimeElapsed);
		this.onToast?.(`🏆 VITÓRIA ÉPICA! CORRIDA CONTRA O TEMPO CONCLUÍDA EM ${this.totalTimeElapsed.toFixed(1)}s! +$7.500`);
		this.setIdleState();
	}
	failMission() {
		this.active = false;
		this.sound.effect("crash");
		this.onGameOver?.("TEMPO ESGOTADO");
		this.onToast?.("💀 TEMPO ESGOTADO! VOCÊ NÃO CRUZOU O ARCO A TEMPO!");
		this.setIdleState();
	}
	update(dt, playerPos, inVehicle, _playerSpeed) {
		if (this.archCooldownTimer > 0) this.archCooldownTimer -= dt;
		if (this.guideLineTexture && this.active) this.guideLineTexture.offset.x -= dt * 1.8;
		const time = performance.now() * .003;
		for (const arch of this.arches) if (arch.group.visible && arch.hologramMesh) {
			const mat = arch.hologramMesh.material;
			mat.opacity = .18 + Math.sin(time * 3 + arch.id) * .1;
		}
		if (!this.active) {
			const startArch = this.arches[0];
			if (Math.hypot(playerPos.x - startArch.position.x, playerPos.z - startArch.position.z) < 7.5 && playerPos.y < 5 && this.archCooldownTimer <= 0) {
				if (inVehicle) this.startMission();
				else {
					this.onToast?.("🚗 ENTRE EM UM VEÍCULO PARA INICIAR A CORRIDA CONTRA O TEMPO!");
					this.archCooldownTimer = 3;
				}
			}
			return;
		}
		this.timeRemaining -= dt;
		this.totalTimeElapsed += dt;
		this.onTimeTick?.(Math.max(0, this.timeRemaining), this.stageMaxTime);
		const currentSec = Math.ceil(this.timeRemaining);
		if (currentSec <= 5 && currentSec > 0 && currentSec !== this.lastBeepSecond) {
			this.lastBeepSecond = currentSec;
			this.sound.effect("countdown_beep");
		}
		if (this.timeRemaining <= 0) {
			this.failMission();
			return;
		}
		if (this.archCooldownTimer <= 0 && inVehicle) {
			if (this.currentStage === 1) {
				const targetArch = this.arches[1];
				if (Math.hypot(playerPos.x - targetArch.position.x, playerPos.z - targetArch.position.z) < 8 && playerPos.y < 5) this.advanceStage(2);
			} else if (this.currentStage === 2) {
				const targetArch = this.arches[2];
				if (Math.hypot(playerPos.x - targetArch.position.x, playerPos.z - targetArch.position.z) < 8 && playerPos.y < 5) this.advanceStage(3);
			} else if (this.currentStage === 3) {
				const targetArch = this.arches[3];
				if (Math.hypot(playerPos.x - targetArch.position.x, playerPos.z - targetArch.position.z) < 8 && playerPos.y < 5) this.completeVictory();
			}
		}
	}
	getCurrentTargetArch() {
		if (!this.active) return this.arches[0];
		return this.arches[this.currentStage] || null;
	}
	dispose() {
		this.scene.remove(this.root);
		this.guideLineTexture?.dispose();
		this.guideLineMaterial?.dispose();
		for (const mesh of this.stageMeshes) mesh.geometry.dispose();
		for (const arch of this.arches) arch.group.traverse((child) => {
			if (child instanceof Mesh) {
				child.geometry.dispose();
				if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose());
				else child.material.dispose();
			}
		});
	}
};
//#endregion
//#region src/game/Traffic.ts
var BLOCK = 48;
var LANE_OFFSET = 3.1;
var TRAFFIC_COUNT = 28;
var paintColors = [
	4037512,
	15055164,
	7180227,
	13983560,
	14144455,
	10184331,
	6531513,
	6185823
];
var Traffic = class {
	scene;
	units = [];
	constructor(scene) {
		this.scene = scene;
	}
	reset() {
		for (const unit of this.units) unit.car.dispose();
		this.units.length = 0;
	}
	getCars() {
		return this.units.map((unit) => unit.car);
	}
	findNearbyCar(position, maxDistance) {
		let nearest = null;
		let minDistance = maxDistance;
		for (const unit of this.units) {
			const dist = unit.car.root.position.distanceTo(position);
			if (dist <= minDistance) {
				minDistance = dist;
				nearest = {
					car: unit.car,
					distance: dist
				};
			}
		}
		return nearest;
	}
	removeCar(car) {
		const index = this.units.findIndex((unit) => unit.car === car);
		if (index !== -1) {
			this.units.splice(index, 1);
			return true;
		}
		return false;
	}
	update(dt, player, city) {
		const playerPosition = player.root.position;
		const explosions = [];
		const smokingPositions = [];
		if (Math.abs(playerPosition.x) > 420) {
			if (this.units.length > 0) this.reset();
			return {
				playerCollisions: 0,
				collisionPoints: [],
				explosions,
				smokingPositions
			};
		}
		for (let index = this.units.length - 1; index >= 0; index -= 1) {
			const unit = this.units[index];
			const dx = unit.car.root.position.x - playerPosition.x;
			const dz = unit.car.root.position.z - playerPosition.z;
			if (Math.hypot(dx, dz) > 205 || unit.car.exploded && unit.car.hitCooldown <= 0) {
				unit.car.dispose();
				this.units.splice(index, 1);
			}
		}
		let spawnBudget = 2;
		while (this.units.length < TRAFFIC_COUNT && spawnBudget > 0) {
			this.spawn(playerPosition);
			spawnBudget--;
		}
		for (const unit of this.units) {
			if (!unit.car.exploded) this.move(unit, dt, player, city);
			if (unit.car.isSmoking) {
				unit.car.smokeTimer += dt;
				if (unit.car.smokeTimer >= .09) {
					unit.car.smokeTimer = 0;
					smokingPositions.push(unit.car.getHoodPosition());
				}
			}
		}
		const collisionPoints = [];
		let playerCollisions = 0;
		for (let index = 0; index < this.units.length; index += 1) {
			const unit = this.units[index];
			unit.impactCooldown = Math.max(0, unit.impactCooldown - dt);
			if (unit.car.exploded) continue;
			const playerDx = player.root.position.x - unit.car.root.position.x;
			const playerDz = player.root.position.z - unit.car.root.position.z;
			if (playerDx * playerDx + playerDz * playerDz < 81 && player.collideWith(unit.car, dt)) {
				if (unit.impactCooldown === 0) {
					playerCollisions += 1;
					collisionPoints.push(this.contactPoint(player, unit.car));
					unit.impactCooldown = .45;
					if (unit.car.registerHit("vehicle", .45).isNewExplosion) explosions.push(unit.car.root.position.clone());
					if (unit.turn) unit.turn = null;
				}
			}
			for (let otherIndex = index + 1; otherIndex < this.units.length; otherIndex += 1) {
				const other = this.units[otherIndex];
				if (other.car.exploded) continue;
				const dx = unit.car.root.position.x - other.car.root.position.x;
				const dz = unit.car.root.position.z - other.car.root.position.z;
				if (dx * dx + dz * dz > 225) continue;
				if (!unit.car.collideWith(other.car, dt)) continue;
				if (unit.impactCooldown === 0 && other.impactCooldown === 0) {
					collisionPoints.push(this.contactPoint(unit.car, other.car));
					unit.impactCooldown = .45;
					other.impactCooldown = .45;
					const hitA = unit.car.registerHit("vehicle", .45);
					const hitB = other.car.registerHit("vehicle", .45);
					if (hitA.isNewExplosion) explosions.push(unit.car.root.position.clone());
					if (hitB.isNewExplosion) explosions.push(other.car.root.position.clone());
					if (unit.turn) unit.turn = null;
					if (other.turn) other.turn = null;
				}
			}
		}
		return {
			playerCollisions,
			collisionPoints,
			explosions,
			smokingPositions
		};
	}
	spawn(player) {
		const axis = Math.random() < .53 ? "z" : "x";
		const direction = Math.random() < .5 ? -1 : 1;
		const kind = this.chooseKind();
		let x;
		let z;
		if (axis === "z") {
			const road = MathUtils.clamp(Math.round(player.x / BLOCK) + Math.floor(Math.random() * 9) - 4, -7, 7) * BLOCK;
			z = player.z + (Math.random() * 2 - 1) * 145;
			if (Math.abs(z - player.z) < 25 && Math.abs(road - player.x) < 16) z += direction * 38;
			x = road - direction * LANE_OFFSET;
		} else {
			const road = Math.round((player.z + (Math.random() * 2 - 1) * 140) / BLOCK) * BLOCK;
			x = MathUtils.clamp(player.x + (Math.random() * 2 - 1) * 175, -330, 330);
			if (Math.abs(x - player.x) < 25 && Math.abs(road - player.z) < 16) x += direction * 38;
			z = road + direction * LANE_OFFSET;
		}
		const cruiseSpeed = kind === "bicycle" ? 3.8 + Math.random() * 3.5 : kind === "fuel_tanker" || kind === "car_hauler" ? 7.2 + Math.random() * 4 : kind === "truck" || kind === "bus" ? 6.5 + Math.random() * 4.5 : kind === "pickup" || kind === "suv" ? 9 + Math.random() * 7 : 11 + Math.random() * 8;
		const colors = kind === "bus" ? 14723108 : kind === "fuel_tanker" ? 15791094 : kind === "car_hauler" ? 2450411 : kind === "taxi" ? 16436245 : paintColors[Math.floor(Math.random() * paintColors.length)];
		const scale = kind === "bicycle" ? .88 : kind === "truck" || kind === "bus" || kind === "fuel_tanker" || kind === "car_hauler" ? .98 : 1;
		const car = new Car(this.scene, {
			kind,
			color: colors,
			scale
		});
		car.setGraphicsMode(this.graphicsMode);
		if (kind === "bicycle") car.setRiderVisible(true);
		const yaw = this.heading(axis, direction);
		car.setPosition(x, z, yaw);
		car.speed = cruiseSpeed;
		const coordinate = axis === "z" ? z : x;
		this.units.push({
			car,
			axis,
			direction,
			nextIntersection: this.nextGridCoordinate(coordinate, direction),
			cruiseSpeed,
			acceleration: kind === "truck" || kind === "bus" || kind === "fuel_tanker" || kind === "car_hauler" ? 2 : kind === "bicycle" ? 2.8 : 3.4,
			impactCooldown: 0,
			turn: null,
			decisionIntersection: null
		});
	}
	chooseKind() {
		const roll = Math.random();
		if (roll < .14) return "sedan";
		if (roll < .25) return "taxi";
		if (roll < .37) return "suv";
		if (roll < .47) return "pickup";
		if (roll < .56) return "truck";
		if (roll < .7) return "car_hauler";
		if (roll < .81) return "fuel_tanker";
		if (roll < .9) return "bus";
		return "bicycle";
	}
	move(unit, dt, player, city) {
		if (unit.turn) {
			this.advanceTurn(unit, dt);
			return;
		}
		const car = unit.car;
		let targetSpeed = unit.cruiseSpeed;
		const pos = car.root.position;
		const coordinate = unit.axis === "z" ? pos.z : pos.x;
		const distanceToIntersection = (unit.nextIntersection - coordinate) * unit.direction;
		if (distanceToIntersection > 1 && distanceToIntersection <= 18) {
			const esquinaX = unit.axis === "z" ? Math.round(pos.x / BLOCK) * BLOCK : unit.nextIntersection;
			const esquinaZ = unit.axis === "z" ? unit.nextIntersection : Math.round(pos.z / BLOCK) * BLOCK;
			if (city.isTrafficLightRedFor(esquinaX, esquinaZ, unit.axis)) targetSpeed = 0;
		}
		for (const other of this.units) {
			if (other === unit) continue;
			if (other.axis === unit.axis && other.direction === unit.direction) {
				const dx = other.car.root.position.x - car.root.position.x;
				const dz = other.car.root.position.z - car.root.position.z;
				const forwardDist = unit.axis === "z" ? dz * unit.direction : dx * unit.direction;
				if ((unit.axis === "z" ? Math.abs(dx) : Math.abs(dz)) < 2.5 && forwardDist > 0 && forwardDist < 10) {
					targetSpeed = Math.min(targetSpeed, Math.max(0, other.car.speed * .85));
					break;
				}
			}
		}
		if (unit.car.kind !== "fuel_tanker") {
			const activeTankers = [];
			if (player.kind === "fuel_tanker" && !player.exploded) activeTankers.push(player);
			for (const u of this.units) if (u.car.kind === "fuel_tanker" && !u.car.exploded && u !== unit) activeTankers.push(u.car);
			for (const tanker of activeTankers) {
				const dx = tanker.root.position.x - car.root.position.x;
				const dz = tanker.root.position.z - car.root.position.z;
				const distSq = dx * dx + dz * dz;
				if (distSq < 676) {
					const dist = Math.sqrt(distSq);
					if (dist > .1) {
						const evadeStrength = Math.min(1, (26 - dist) / 18);
						if (unit.axis === "z") {
							const sideSign = car.root.position.x >= tanker.root.position.x ? 1 : -1;
							car.root.position.x += sideSign * 9.5 * evadeStrength * dt;
						} else {
							const sideSign = car.root.position.z >= tanker.root.position.z ? 1 : -1;
							car.root.position.z += sideSign * 9.5 * evadeStrength * dt;
						}
						const forwardDist = unit.axis === "z" ? dz * unit.direction : dx * unit.direction;
						if (forwardDist > 0 && forwardDist < 16) targetSpeed = Math.min(targetSpeed, -2);
					}
				}
			}
		}
		const speedDelta = MathUtils.clamp(targetSpeed - car.speed, -unit.acceleration * dt * 1.5, unit.acceleration * dt);
		car.speed += speedDelta;
		if (unit.axis === "z") {
			const targetX = Math.round(pos.x / BLOCK) * BLOCK - unit.direction * LANE_OFFSET;
			pos.x += (targetX - pos.x) * Math.min(1, dt * 5);
		} else {
			const targetZ = Math.round(pos.z / BLOCK) * BLOCK + unit.direction * LANE_OFFSET;
			pos.z += (targetZ - pos.z) * Math.min(1, dt * 5);
		}
		if (distanceToIntersection <= 7.8 && distanceToIntersection > 1 && unit.decisionIntersection !== unit.nextIntersection) {
			unit.decisionIntersection = unit.nextIntersection;
			if (this.tryInitiateTurn(unit)) {
				this.advanceTurn(unit, dt);
				return;
			}
		}
		if (distanceToIntersection <= -.5) {
			unit.nextIntersection += unit.direction * BLOCK;
			unit.decisionIntersection = null;
		}
		const x = car.root.position.x;
		if (unit.axis === "x" && (x > 330 && unit.direction > 0 || x < -330 && unit.direction < 0)) {
			unit.axis = "z";
			unit.direction = Math.random() < .5 ? 1 : -1;
			this.setLane(unit);
			car.yaw = this.heading(unit.axis, unit.direction);
			car.root.rotation.set(0, car.yaw, 0);
			unit.nextIntersection = this.nextGridCoordinate(car.root.position.z, unit.direction);
			unit.decisionIntersection = null;
			return;
		}
		car.yaw = this.heading(unit.axis, unit.direction);
		car.root.rotation.set(0, car.yaw, 0);
		car.integrateMovement(dt);
	}
	tryInitiateTurn(unit) {
		const car = unit.car;
		const currentAxis = unit.axis;
		const currentDir = unit.direction;
		let targetAxis;
		let targetDir;
		let Ix;
		let Iz;
		if (currentAxis === "z") {
			Ix = Math.round(car.root.position.x / BLOCK) * BLOCK;
			Iz = unit.nextIntersection;
			targetAxis = "x";
			const canGoEast = Ix < 326;
			const canGoWest = Ix > -326;
			if (!canGoEast && !canGoWest) return false;
			if (Math.random() > .32) return false;
			if (canGoEast && canGoWest) targetDir = Math.random() < .5 ? 1 : -1;
			else targetDir = canGoEast ? 1 : -1;
		} else {
			Ix = unit.nextIntersection;
			Iz = Math.round(car.root.position.z / BLOCK) * BLOCK;
			targetAxis = "z";
			if (Ix >= 321 && currentDir > 0 || Ix <= -321 && currentDir < 0) targetDir = Math.random() < .5 ? 1 : -1;
			else {
				if (Math.random() > .32) return false;
				targetDir = Math.random() < .5 ? 1 : -1;
			}
		}
		let isRightTurn = false;
		if (currentAxis === "z") isRightTurn = currentDir === 1 && targetDir === -1 || currentDir === -1 && targetDir === 1;
		else isRightTurn = currentDir === 1 && targetDir === 1 || currentDir === -1 && targetDir === -1;
		const Din = isRightTurn ? 6.2 : 7.6;
		const Dout = isRightTurn ? 6.2 : 7.6;
		let p0;
		let t0;
		if (currentAxis === "z") {
			p0 = new Vector2(car.root.position.x, Iz - currentDir * Din);
			t0 = new Vector2(0, currentDir);
		} else {
			p0 = new Vector2(Ix - currentDir * Din, car.root.position.z);
			t0 = new Vector2(currentDir, 0);
		}
		let p1;
		let t1;
		if (targetAxis === "x") {
			p1 = new Vector2(Ix + targetDir * Dout, Iz + targetDir * LANE_OFFSET);
			t1 = new Vector2(targetDir, 0);
		} else {
			p1 = new Vector2(Ix - targetDir * LANE_OFFSET, Iz + targetDir * Dout);
			t1 = new Vector2(0, targetDir);
		}
		const L = p0.distanceTo(p1) * .44;
		const c0 = new Vector2(p0.x + t0.x * L, p0.y + t0.y * L);
		const c1 = new Vector2(p1.x - t1.x * L, p1.y - t1.y * L);
		const arcLength = this.bezierLength(p0, c0, c1, p1);
		const turnSpeed = Math.max(4.8, unit.cruiseSpeed * .78);
		const duration = Math.max(.65, arcLength / turnSpeed);
		unit.turn = {
			p0,
			c0,
			c1,
			p1,
			targetAxis,
			targetDirection: targetDir,
			progress: 0,
			duration,
			speed: turnSpeed
		};
		return true;
	}
	advanceTurn(unit, dt) {
		const turn = unit.turn;
		const car = unit.car;
		turn.progress += dt / turn.duration;
		const t = Math.min(1, turn.progress);
		const pos = new Vector2();
		this.bezierPoint(turn.p0, turn.c0, turn.c1, turn.p1, t, pos);
		car.root.position.set(pos.x, 0, pos.y);
		const tangent = new Vector2();
		this.bezierDerivative(turn.p0, turn.c0, turn.c1, turn.p1, t, tangent);
		if (tangent.lengthSq() > 1e-4) {
			const yaw = Math.atan2(-tangent.x, -tangent.y);
			car.yaw = yaw;
			car.root.rotation.set(0, yaw, 0);
		}
		car.speed = turn.speed;
		const wheelSpin = -car.speed * dt / .38;
		for (const wheel of car.wheels) wheel.rotation.x += wheelSpin;
		if (t >= 1) {
			unit.axis = turn.targetAxis;
			unit.direction = turn.targetDirection;
			unit.turn = null;
			car.yaw = this.heading(unit.axis, unit.direction);
			car.root.rotation.set(0, car.yaw, 0);
			const currentCoord = unit.axis === "z" ? car.root.position.z : car.root.position.x;
			unit.nextIntersection = this.nextGridCoordinate(currentCoord, unit.direction);
			unit.decisionIntersection = null;
			this.setLane(unit);
		}
	}
	bezierPoint(p0, c0, c1, p1, t, out) {
		const u = 1 - t;
		const tt = t * t;
		const uu = u * u;
		const uuu = uu * u;
		const ttt = tt * t;
		out.x = uuu * p0.x + 3 * uu * t * c0.x + 3 * u * tt * c1.x + ttt * p1.x;
		out.y = uuu * p0.y + 3 * uu * t * c0.y + 3 * u * tt * c1.y + ttt * p1.y;
	}
	bezierDerivative(p0, c0, c1, p1, t, out) {
		const u = 1 - t;
		const a = 3 * u * u;
		const b = 6 * u * t;
		const c = 3 * t * t;
		out.x = a * (c0.x - p0.x) + b * (c1.x - c0.x) + c * (p1.x - c1.x);
		out.y = a * (c0.y - p0.y) + b * (c1.y - c0.y) + c * (p1.y - c1.y);
	}
	bezierLength(p0, c0, c1, p1, samples = 8) {
		let length = 0;
		let prevX = p0.x;
		let prevY = p0.y;
		const temp = new Vector2();
		for (let i = 1; i <= samples; i++) {
			const t = i / samples;
			this.bezierPoint(p0, c0, c1, p1, t, temp);
			length += Math.hypot(temp.x - prevX, temp.y - prevY);
			prevX = temp.x;
			prevY = temp.y;
		}
		return length;
	}
	setLane(unit) {
		const position = unit.car.root.position;
		if (unit.axis === "z") position.x = Math.round(position.x / BLOCK) * BLOCK - unit.direction * LANE_OFFSET;
		else position.z = Math.round(position.z / BLOCK) * BLOCK + unit.direction * LANE_OFFSET;
	}
	nextGridCoordinate(coordinate, direction) {
		const grid = coordinate / BLOCK;
		return (direction > 0 ? Math.floor(grid) + 1 : Math.ceil(grid) - 1) * BLOCK;
	}
	heading(axis, direction) {
		if (axis === "z") return direction > 0 ? Math.PI : 0;
		return direction > 0 ? -Math.PI / 2 : Math.PI / 2;
	}
	contactPoint(first, second) {
		return new Vector3((first.root.position.x + second.root.position.x) / 2, .92, (first.root.position.z + second.root.position.z) / 2);
	}
	graphicsMode = "medium";
	setGraphicsMode(mode) {
		this.graphicsMode = mode;
		for (const unit of this.units) unit.car.setGraphicsMode(mode);
	}
	dispose() {
		this.reset();
	}
};
