				const halfD = this.arenaBounds.depth / 2 - 4.5;
				const targetX = MathUtils.clamp(playerPos.x + (Math.random() - .5) * 22, this.arenaBounds.centerX - halfW, this.arenaBounds.centerX + halfW);
				const targetZ = MathUtils.clamp(playerPos.z + (Math.random() - .5) * 22, this.arenaBounds.centerZ - halfD, this.arenaBounds.centerZ + halfD);
