function getNativePlatform() {
	return {
		isNative: Capacitor.isNativePlatform(),
		platform: Capacitor.getPlatform()
	};
}
async function initCapacitorBridge(callbacks) {
	const { isNative, platform } = getNativePlatform();
	if (!isNative) return;
	try {
		if (Capacitor.isPluginAvailable("StatusBar")) {
			await StatusBar.setOverlaysWebView({ overlay: true });
			await StatusBar.setStyle({ style: Style.Dark });
			if (platform === "android") await StatusBar.setBackgroundColor({ color: "#111412" });
		}
	} catch (err) {
		console.warn("[Capacitor] Erro ao configurar StatusBar:", err);
	}
	try {
		if (Capacitor.isPluginAvailable("SplashScreen")) setTimeout(async () => {
			try {
				await SplashScreen.hide({ fadeOutDuration: 400 });
			} catch {}
		}, 500);
	} catch (err) {
		console.warn("[Capacitor] Erro ao ocultar SplashScreen:", err);
	}
	try {
		if (Capacitor.isPluginAvailable("App")) App.addListener("backButton", ({ canGoBack }) => {
			if (callbacks?.onBackButtonPressed) {
				if (callbacks.onBackButtonPressed()) return;
			}
			for (const selector of [
				"#settings-modal",
				"#shop-modal",
				"#leaderboard-modal",
				"#auth-modal"
			]) {
				const el = document.querySelector(selector);
				if (el && !el.classList.contains("hidden")) {
					el.classList.add("hidden");
					return;
				}
			}
			const pauseOverlay = document.querySelector("#pause-overlay");
			if (pauseOverlay && !pauseOverlay.classList.contains("hidden")) {
				const resumeBtn = document.querySelector("#resume-button");
				if (resumeBtn) {
					resumeBtn.click();
					return;
				}
			}
			if (canGoBack) window.history.back();
			else App.minimizeApp();
		});
	} catch (err) {
		console.warn("[Capacitor] Erro ao configurar backButton do App:", err);
	}
}
/**
* Gatilho de Vibração Tátil Nativa (Haptics)
* Dispara vibrações hápticas imersivas no controle do jogador ao colidir ou usar turbo
*/
async function triggerHapticImpact(style = "medium") {
	if (Capacitor.isNativePlatform() && Capacitor.isPluginAvailable("Haptics")) try {
		const styleMap = {
			light: ImpactStyle.Light,
			medium: ImpactStyle.Medium,
			heavy: ImpactStyle.Heavy
		};
		await Haptics.impact({ style: styleMap[style] });
		return;
	} catch {}
	if (typeof navigator !== "undefined" && typeof navigator.vibrate === "function") try {
		const duration = style === "heavy" ? 40 : style === "medium" ? 22 : 12;
		navigator.vibrate(duration);
	} catch {}
}
/**
* Vibração de Notificação de Sucesso ou Alerta (Haptics)
*/
async function triggerHapticNotification(type = "success") {
	if (Capacitor.isNativePlatform() && Capacitor.isPluginAvailable("Haptics")) try {
		const typeMap = {
			success: NotificationType.Success,
			warning: NotificationType.Warning,
			error: NotificationType.Error
		};
		await Haptics.notification({ type: typeMap[type] });
		return;
	} catch {}
	if (typeof navigator !== "undefined" && typeof navigator.vibrate === "function") try {
		navigator.vibrate(type === "success" ? [
			15,
			40,
			25
		] : [
			30,
			50,
			40
		]);
	} catch {}
}
